from _lib import *
G = Gen('m08', 17, 20250808, dict(reg=('Regulation and regulator blocks', 'Điều chỉnh và các khối của bộ ổn áp'), ser=('Series regulators and current limiting', 'Ổn áp nối tiếp và giới hạn dòng'), shu=('Shunt regulators', 'Ổn áp song song'), sw=('Switching regulators', 'Ổn áp xung'), ic=('IC regulators', 'IC ổn áp')))
g, fmt, add = G.g, G.fmt, G.add; S = lambda a, b: (a, b)
for vn, dv, vi_a, vi_b in [(8, 2, 12, 18), (5, 1, 8, 15), (12, 6, 15, 25), (15, 3, 20, 30), (9, 4.5, 12, 20)]:
    lr = dv * 1e-3 / (vi_b - vi_a) * 100
    add('reg', f'A regulator (nominal output {vn} V) changes {dv} mV when VIN goes from {vi_a} V to {vi_b} V. What is the line regulation in %/V?', f'Bộ ổn áp (danh định {vn} V) đổi {dv} mV khi VIN đi từ {vi_a} V đến {vi_b} V. Line regulation là bao nhiêu %/V?', f'{lr/(vi_b-vi_a):.3g} %/V', [f'{lr:.3g} %/V', f'{lr*(vi_b-vi_a)**2:.3g} %/V', f'{dv/(vi_b-vi_a):.3g} %/V', f'{dv*1e-3/vn*100/(vi_b-vi_a):.3g} %/V'], f'ΔVOUT/ΔVIN × 100 % = ({dv} mV/{vi_b-vi_a} V) × 100 % = {lr:.3g} % over the range, i.e. {lr/(vi_b-vi_a):.3g} %/V.', f'ΔVOUT/ΔVIN × 100 % = ({dv} mV/{vi_b-vi_a} V) × 100 % = {lr:.3g} % trên cả dải, tức {lr/(vi_b-vi_a):.3g} %/V.', S('Floyd Problem 2', 'Floyd Bài 2'), 2)
for vnl, vfl in [(10, 9.9), (5.02, 4.95), (12.1, 11.8), (15, 14.7), (9.1, 9.0)]:
    lr = (vnl - vfl) / vfl * 100
    add('reg', f'A regulator has VNL = {vnl} V and VFL = {vfl} V. What is the percent load regulation?', f'Bộ ổn áp có VNL = {vnl} V và VFL = {vfl} V. Load regulation theo phần trăm là bao nhiêu?', f'{lr:.3g} %', [f'{(vnl-vfl)/vnl*100:.3g} %', f'{(vnl-vfl):.3g} %', f'{lr*2:.3g} %', f'{vfl/vnl*100:.3g} %'], f'(VNL − VFL)/VFL × 100 % = ({vnl} − {vfl})/{vfl} × 100 % = {lr:.3g} %.', f'(VNL − VFL)/VFL × 100 % = ({vnl} − {vfl})/{vfl} × 100 % = {lr:.3g} %.', S('Floyd Problem 3', 'Floyd Bài 3'), 2)
for r2, r3, vr in [(5.6, 2.2, 2.4), (10, 10, 5.1), (22, 10, 3.3), (4.7, 1.0, 1.25), (33, 12, 2.5)]:
    vo = (1 + r2 / r3) * vr
    add('ser', f'A series regulator has R2 = {r2} kΩ, R3 = {r3} kΩ and a reference of {vr} V. What is VOUT? (VOUT = (1 + R2/R3)·VREF)', f'Ổn áp nối tiếp có R2 = {r2} kΩ, R3 = {r3} kΩ và tham chiếu {vr} V. VOUT là bao nhiêu? (VOUT = (1 + R2/R3)·VREF)', fmt(vo, 'V'), [fmt(r2 / r3 * vr, 'V'), fmt((1 + r3 / r2) * vr, 'V'), fmt(vr, 'V'), fmt(vo + 0.7, 'V')], f'VOUT = (1 + {r2}/{r3}) × {vr} = {g(vo)} V.', f'VOUT = (1 + {r2}/{r3}) × {vr} = {g(vo)} V.', S('Floyd Problem 7', 'Floyd Bài 7'), 2)
for vo, vr, r3 in [(12, 5.1, 10), (9, 2.4, 3.3), (5, 1.25, 2.2), (15, 5.1, 4.7)]:
    r2 = (vo / vr - 1) * r3
    add('ser', f'A series regulator with VREF = {vr} V and R3 = {r3} kΩ must give VOUT = {vo} V. What R2 is needed?', f'Ổn áp nối tiếp có VREF = {vr} V và R3 = {r3} kΩ phải cho VOUT = {vo} V. Cần R2 bằng bao nhiêu?', fmt(r2, 'kΩ'), [fmt(vo / vr * r3, 'kΩ'), fmt((vr / vo - 1) * r3 if vr / vo > 1 else r3 * vr / vo, 'kΩ'), fmt(r2 * 2, 'kΩ'), fmt(r3 * (vo - vr), 'kΩ')], f'R2 = (VOUT/VREF − 1)·R3 = ({vo}/{vr} − 1) × {r3} = {g(r2)} kΩ.', f'R2 = (VOUT/VREF − 1)·R3 = ({vo}/{vr} − 1) × {r3} = {g(r2)} kΩ.', S('Floyd Problem 7', 'Floyd Bài 7'), 3)
for imax in [250, 500, 100, 1000, 2000]:
    r4 = 0.7 / (imax * 1e-3)
    add('ser', f'A current-limiting resistor must hold the load current to {imax} mA (the limiting transistor turns on at 0.7 V). What is R?', f'Điện trở giới hạn phải giữ dòng tải ở {imax} mA (transistor giới hạn dẫn ở 0,7 V). R bằng bao nhiêu?', fmt(r4, 'Ω'), [fmt(r4 * 10, 'Ω'), fmt(r4 / 10, 'Ω'), fmt(imax / 0.7, 'Ω'), fmt(r4 * 2, 'Ω')], f'R = 0.7 V/{imax} mA = {g(r4)} Ω.', f'R = 0,7 V/{imax} mA = {g(r4)} Ω.', S('Floyd Problem 10', 'Floyd Bài 10'), 2)
for r1, dv in [(100, 1), (47, 2), (220, 5), (100, 0.5)]:
    di = dv / r1 * 1e3
    add('shu', f'In a shunt regulator with series resistor R1 = {r1} Ω, VIN changes by {dv} V while IL stays constant. What is the change in the shunt current?', f'Ở ổn áp song song có điện trở nối tiếp R1 = {r1} Ω, VIN đổi {dv} V trong khi IL không đổi. Dòng shunt thay đổi bao nhiêu?', fmt(di, 'mA'), [fmt(di / 1000, 'mA'), fmt(di * r1, 'mA'), fmt(dv * r1, 'mA'), fmt(di * 2, 'mA')], f'ΔI = ΔVIN/R1 = {dv} V/{r1} Ω = {g(di)} mA.', f'ΔI = ΔVIN/R1 = {dv} V/{r1} Ω = {g(di)} mA.', S('Floyd Problem 13', 'Floyd Bài 13'), 2)
for vmax, r1 in [(25, 100), (20, 47), (15, 22), (30, 100)]:
    isc = vmax / r1 * 1e3; p = vmax ** 2 / r1
    add('shu', f'A shunt regulator has R1 = {r1} Ω and VIN(max) = {vmax} V. What power rating must R1 have when the output is shorted?', f'Ổn áp song song có R1 = {r1} Ω và VIN(max) = {vmax} V. R1 phải có công suất định mức bao nhiêu khi ngắn mạch ngõ ra?', fmt(p, 'W'), [fmt(isc / 1000, 'W'), fmt(p / 2, 'W'), fmt(vmax * r1, 'W'), fmt(p * 4, 'W')], f'P = VIN²/R1 = {vmax}²/{r1} = {g(p)} W (short-circuit current {g(isc)} mA).', f'P = VIN²/R1 = {vmax}²/{r1} = {g(p)} W (dòng ngắn mạch {g(isc)} mA).', S('Floyd Problem 15', 'Floyd Bài 15'), 2)
for toff, f_, vin in [(60, 10, 12), (30, 20, 15), (25, 25, 20), (80, 5, 24), (10, 50, 12)]:
    t = 1000 / f_; ton = t - toff; d = ton / t * 100
    if ton <= 0: continue
    add('sw', f'A switching regulator transistor runs at {f_} kHz with an off-time of {toff} μs. What is the duty cycle?', f'Transistor của ổn áp xung chạy ở {f_} kHz với thời gian tắt {toff} μs. Chu kỳ làm việc là bao nhiêu?', f'{d:.3g} %', [f'{toff/t*100:.3g} %', f'{ton/toff*100:.3g} %', f'{100-d/2:.3g} %', f'{d*2:.3g} %'], f'T = 1/{f_} kHz = {g(t)} μs; ton = {g(t)} − {toff} = {g(ton)} μs; duty = {g(d)} %.', f'T = 1/{f_} kHz = {g(t)} μs; ton = {g(t)} − {toff} = {g(ton)} μs; chu kỳ = {g(d)} %.', S('Floyd Problem 17', 'Floyd Bài 17'), 2)
    add('sw', f'A step-down switching regulator with VIN = {vin} V runs at a duty cycle of {d:.3g} % (ideal switch). What is VOUT?', f'Ổn áp xung giảm áp có VIN = {vin} V chạy với chu kỳ làm việc {d:.3g} % (công tắc lý tưởng). VOUT là bao nhiêu?', fmt(vin * d / 100, 'V'), [fmt(vin * (1 - d / 100), 'V'), fmt(vin / (d / 100), 'V'), fmt(vin, 'V'), fmt(vin * d / 100 * 2, 'V')], f'VOUT = duty × VIN = {d:.3g} % × {vin} = {g(vin*d/100)} V.', f'VOUT = chu kỳ × VIN = {d:.3g} % × {vin} = {g(vin*d/100)} V.', S('Floyd Problem 16', 'Floyd Bài 16'), 2)
for r1, r2 in [(1.0, 10), (240, 720), (220, 2200), (330, 1000), (470, 4700)]:
    vo = 1.25 * (1 + r2 / r1) + 50e-6 * r2 * (1e3 if r1 < 10 else 1) * 0
    k = 1e3 if r1 < 10 else 1; vo = 1.25 * (1 + r2 / r1) + 50e-6 * r2 * k
    add('ic', f'An LM317 has R1 = {r1} {"kΩ" if r1<10 else "Ω"} and R2 = {r2} {"kΩ" if r1<10 else "Ω"} and IADJ = 50 μA. What is VOUT? (VOUT = 1.25(1 + R2/R1) + IADJ·R2)', f'LM317 có R1 = {r1} {"kΩ" if r1<10 else "Ω"}, R2 = {r2} {"kΩ" if r1<10 else "Ω"} và IADJ = 50 μA. VOUT là bao nhiêu? (VOUT = 1,25(1 + R2/R1) + IADJ·R2)', fmt(vo, 'V'), [fmt(1.25 * (1 + r2 / r1), 'V'), fmt(1.25 * r2 / r1, 'V'), fmt(1.25 * (1 + r1 / r2) + 50e-6 * r2 * k, 'V'), fmt(vo * 2, 'V')], f'VOUT = 1.25(1 + {r2}/{r1}) + 50 μA × {r2} {"kΩ" if r1<10 else "Ω"} = {g(1.25*(1+r2/r1))} + {g(50e-6*r2*k)} = {g(vo)} V.', f'VOUT = 1,25(1 + {r2}/{r1}) + 50 μA × {r2} {"kΩ" if r1<10 else "Ω"} = {g(1.25*(1+r2/r1))} + {g(50e-6*r2*k)} = {g(vo)} V.', S('Floyd Problem 21', 'Floyd Bài 21'), 3)
for code, v in [('7805', '+5 V'), ('7812', '+12 V'), ('7915', '−15 V'), ('7824', '+24 V'), ('7908', '−8 V'), ('7809', '+9 V')]:
    ws = [x for x in ['+5 V', '+12 V', '−15 V', '+24 V', '−8 V', '+9 V', '−5 V', '+15 V', '−12 V'] if x != v]
    add('ic', f'What is the output voltage of a {code} IC regulator?', f'Điện áp ra của IC ổn áp {code} là bao nhiêu?', v, ws[:6], f'78XX = positive, 79XX = negative; the last two digits give the voltage: {v}.', f'78XX = dương, 79XX = âm; hai chữ số cuối cho điện áp: {v}.', S('Floyd Problem 20', 'Floyd Bài 20'))
for imax in [250, 500, 100, 1000]:
    rx = 0.7 / (imax * 1e-3)
    add('ic', f'In a 78XX circuit with an external pass transistor, what Rext limits the internal regulator current to {imax} mA?', f'Trong mạch 78XX có transistor pass ngoài, Rext nào giới hạn dòng bên trong bộ ổn áp ở {imax} mA?', fmt(rx, 'Ω'), [fmt(rx * 10, 'Ω'), fmt(rx / 10, 'Ω'), fmt(imax / 0.7, 'Ω'), fmt(rx * 2, 'Ω')], f'Rext = 0.7 V/{imax} mA = {g(rx)} Ω.', f'Rext = 0,7 V/{imax} mA = {g(rx)} Ω.', S('Floyd Problem 25', 'Floyd Bài 25'), 2)
C = [('reg','Good line regulation means the output voltage','Line regulation tốt nghĩa là điện áp ra',('changes very little when the input voltage changes','thay đổi rất ít khi điện áp vào thay đổi'),[('changes a lot when the input changes','thay đổi nhiều khi điện áp vào đổi'),('equals the input voltage','bằng điện áp vào'),('is zero at no load','bằng không khi không tải')],'A small ΔVOUT/ΔVIN is good.','ΔVOUT/ΔVIN nhỏ là tốt.'),
 ('reg','Good load regulation means the output voltage','Load regulation tốt nghĩa là điện áp ra',('stays nearly the same from no load to full load','gần như không đổi từ không tải đến đầy tải'),[('doubles at full load','tăng gấp đôi khi đầy tải'),('collapses at full load','sụp xuống khi đầy tải'),('depends on the input ripple','phụ thuộc gợn điện áp vào')],'(VNL − VFL)/VFL should be small.','(VNL − VFL)/VFL phải nhỏ.'),
 ('reg','The block of a regulator that compares the sampled output with the reference is the','Khối của bộ ổn áp so sánh điện áp lấy mẫu với tham chiếu là',('error detector','bộ phát hiện sai số'),[('control element','phần tử điều khiển'),('heat sink','tản nhiệt'),('filter capacitor','tụ lọc')],'The error signal drives the control element.','Tín hiệu sai số điều khiển phần tử điều khiển.'),
 ('ser','In a series linear regulator the pass transistor power dissipation is approximately','Công suất tiêu tán của transistor pass trong ổn áp tuyến tính nối tiếp xấp xỉ',('(VIN − VOUT)·IL','(VIN − VOUT)·IL'),[('VOUT·IL','VOUT·IL'),('VIN·IL','VIN·IL'),('zero','bằng không')],'The excess voltage drops across the pass element.','Phần điện áp thừa rơi trên phần tử pass.'),
 ('ser','A series regulator’s reference voltage is usually provided by','Điện áp tham chiếu của ổn áp nối tiếp thường do',('a zener diode','một điốt zener'),[('a capacitor','một tụ điện'),('an inductor','một cuộn cảm'),('the load','tải')],'The zener provides a stable VREF.','Zener cung cấp VREF ổn định.'),
 ('shu','A shunt regulator is less efficient than a series regulator mainly because','Ổn áp song song kém hiệu suất hơn ổn áp nối tiếp chủ yếu vì',('it wastes current in the shunt path even at light load','nó tiêu hao dòng ở nhánh shunt ngay cả khi tải nhẹ'),[('it has no reference','nó không có tham chiếu'),('it uses no transistor','nó không dùng transistor'),('it only works with ac','nó chỉ làm việc với xoay chiều')],'The series resistor always carries the full current.','Điện trở nối tiếp luôn mang toàn bộ dòng.'),
 ('shu','A shunt regulator has an inherent advantage of','Ổn áp song song có ưu điểm vốn có là',('short-circuit protection (current limited by R1)','bảo vệ ngắn mạch (dòng bị R1 giới hạn)'),[('very high efficiency','hiệu suất rất cao'),('no heat','không toả nhiệt'),('higher output than input','điện áp ra lớn hơn điện áp vào')],'Output short-circuit current is limited to VIN/R1.','Dòng ngắn mạch ngõ ra bị giới hạn ở VIN/R1.'),
 ('sw','Compared with a linear regulator, a switching regulator is','So với ổn áp tuyến tính, ổn áp xung',('more efficient but noisier','hiệu suất cao hơn nhưng nhiễu hơn'),[('less efficient and quieter','hiệu suất thấp hơn và yên tĩnh hơn'),('always cheaper','luôn rẻ hơn'),('limited to a fixed output','chỉ cho điện áp ra cố định')],'The switch dissipates little but generates ripple/EMI.','Công tắc tiêu tán ít nhưng sinh gợn/nhiễu điện từ.'),
 ('sw','A step-up (boost) switching regulator produces an output that is','Ổn áp xung tăng áp (boost) cho điện áp ra',('greater than the input voltage','lớn hơn điện áp vào'),[('smaller than the input voltage','nhỏ hơn điện áp vào'),('always negative','luôn âm'),('equal to the duty cycle','bằng chu kỳ làm việc')],'The inductor’s stored energy adds to VIN.','Năng lượng tích trong cuộn cảm cộng vào VIN.'),
 ('sw','In the step-down switching regulator, the LC filter','Trong ổn áp xung giảm áp, bộ lọc LC',('smooths the pulses into an average dc voltage','làm phẳng các xung thành điện áp một chiều trung bình'),[('increases the switching frequency','tăng tần số đóng ngắt'),('produces the reference','tạo điện áp tham chiếu'),('limits current only','chỉ giới hạn dòng')],'The average of the pulse train is duty × VIN.','Trung bình của chuỗi xung là chu kỳ × VIN.'),
 ('ic','The 78XX series regulators are','Họ ổn áp 78XX là',('fixed positive regulators','ổn áp dương cố định'),[('fixed negative regulators','ổn áp âm cố định'),('adjustable positive regulators','ổn áp dương điều chỉnh được'),('switching regulators','ổn áp xung')],'The 79XX series is the negative counterpart.','Họ 79XX là loại âm tương ứng.'),
 ('ic','The LM317 output is set by','Điện áp ra LM317 được đặt bởi',('two external resistors','hai điện trở ngoài'),[('an internal fixed reference only','chỉ điện áp tham chiếu cố định bên trong'),('the package type','kiểu vỏ'),('the input voltage only','chỉ điện áp vào')],'VOUT = 1.25(1 + R2/R1) + IADJ·R2.','VOUT = 1,25(1 + R2/R1) + IADJ·R2.'),
 ('ic','A heat sink is needed on a linear IC regulator when','Cần tản nhiệt cho IC ổn áp tuyến tính khi',('(VIN − VOUT)·IL is large','(VIN − VOUT)·IL lớn'),[('VOUT is zero','VOUT bằng không'),('the load is open','tải hở'),('the input is ac','điện áp vào là xoay chiều')],'The regulator dissipates the excess voltage times the current.','Bộ ổn áp tiêu tán phần điện áp thừa nhân với dòng.')]
